import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:font_awesome_flutter/font_awesome_flutter.dart';

// لوجوهات المواقع الحقيقية (جوجل، جيت هاب، أبل صور صغيرة، ومايكروسوفت مرسومة بألوانها الرسمية)
final Uint8List _google = base64Decode('');
final Uint8List _github = base64Decode('');
final Uint8List _apple = base64Decode('');

class _MsLogo extends StatelessWidget {
  final double size;
  const _MsLogo(this.size);
  @override
  Widget build(BuildContext context) {
    final s = size * 0.46;
    final g = size * 0.08;
    Widget q(Color c) => Container(width: s, height: s, color: c);
    return SizedBox(
      width: size,
      height: size,
      child: Center(
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Row(mainAxisSize: MainAxisSize.min, children: [q(const Color(0xFFF25022)), SizedBox(width: g), q(const Color(0xFF7FBA00))]),
          SizedBox(height: g),
          Row(mainAxisSize: MainAxisSize.min, children: [q(const Color(0xFF00A4EF)), SizedBox(width: g), q(const Color(0xFFFFB900))]),
        ]),
      ),
    );
  }
}

Widget brandIcon(IconData icon, double size) {
  Widget img(Uint8List b) => Image.memory(b, width: size, height: size, gaplessPlayback: true, filterQuality: FilterQuality.medium);
  if (icon == FontAwesomeIcons.google) return img(_google);
  if (icon == FontAwesomeIcons.github) return img(_github);
  if (icon == FontAwesomeIcons.apple) return img(_apple);
  if (icon == FontAwesomeIcons.microsoft) return _MsLogo(size);
  return FaIcon(icon, color: Colors.white, size: size);
}
